- alert: GatewaySinLectura                       # el monitoreo que falla en silencio: no hay qué leer
  expr: absent(up{job="gateway"} == 1) or count(up{job="gateway"} == 1) < 2
  for: 30s
  labels: {severity: ticket}
  annotations: {summary: "Prometheus no está leyendo los 2 pods del gateway"}
- alert: ALB5xx                                  # lo que el gateway no ve: el ALB contestando 5xx él mismo
  expr: |
    (sum(rate(alb_httpcode_elb_total{code=~"5.."}[1m])) or vector(0))
      /
    (sum(rate(alb_request_count_total[1m])) + sum(rate(alb_httpcode_elb_total{code=~"5.."}[1m]))) > 0.005
  for: 30s
  labels: {severity: page}
  annotations: {summary: "El ALB contesta 5xx él mismo (sin destinos sanos)"}
